90	// ValidateServerAddress checks the configured server address is correct.
91	func ValidateServerAddress(config *schema.Configuration, validator *schema.StructValidator) {
92		if config.Server.Address == nil {
93			config.Server.Address = schema.DefaultServerConfiguration.Address
94		} else {
95			var err error
96			if err = config.Server.Address.ValidateHTTP(); err != nil {
97				validator.Push(fmt.Errorf(errFmtServerAddress, config.Server.Address.String(), err))
98			}
99		}
100	
101		switch subpath := config.Server.Address.RouterPath(); {
102		case subpath == "":
103			config.Server.Address.SetPath("/")
104		case subpath != "/":
105			if p := strings.TrimPrefix(subpath, "/"); strings.Contains(p, "/") {
106				validator.Push(fmt.Errorf(errFmtServerPathNotEndForwardSlash, subpath))
107			} else if !utils.IsStringAlphaNumeric(p) {
108				validator.Push(fmt.Errorf(errFmtServerPathAlphaNumeric, subpath))
109			}
110		}
111	
112		if config.Server.Address.IsUnixDomainSocket() || config.Server.Address.IsFileDescriptor() {
113			config.Server.DisableHealthcheck = true
114		}
115	}
